    '{R} .ra-close{flex:none;display:inline-flex;align-items:center;justify-content:center;width:34px;height:34px;border-radius:var(--rt-r);transition:background .15s,border-color .15s,color .15s}',

    /* 咖啡馆：夹板与点单纸 */
